import type { FontWeight } from "./fonts.js";
import { FONT_METRICS_DATA, type FaceMetricsData } from "./font-metrics.data.js";

/**
 * Text widths for line breaking. The renderer (FFmpeg drawtext) does not wrap text, so BOTH the browser preview and the
 * renderer take their line breaks from the same measurement: the advance widths of the real font files, in 1/1000 em,
 * generated by packages/video-engine/scripts/generate-font-metrics.ts and verified against the installed fonts by a test.
 * Kerning and shaping are not applied (a line can be a pixel or two wider or narrower than measured; positions that
 * depend on a line's exact width are computed by FFmpeg itself from the real glyphs).
 */
export interface Face {
  data: FaceMetricsData;
  advances: Map<number, number>;
}

const cache = new Map<string, Face>();

export function faceFor(fontId: string, weight: FontWeight): Face | undefined {
  const key = `${fontId}:${weight}`;
  const hit = cache.get(key);
  if (hit) return hit;
  const data = FONT_METRICS_DATA[key];
  if (!data) return undefined;
  const advances = new Map<number, number>();
  for (const [start, list] of data.runs) list.forEach((a, i) => advances.set(start + i, a));
  const face = { data, advances };
  cache.set(key, face);
  return face;
}

/** The no-break space, built from its code so no invisible character sits in the source. */
const NBSP = String.fromCharCode(0xa0);
const TRAILING_SPACES = new RegExp("[ " + NBSP + "]+$");
const AFTER_SPACE = new RegExp("(?<=[ " + NBSP + "])");
const isSpace = (ch: string): boolean => ch === " " || ch === NBSP;
export const isLineBreak = (ch: string): boolean => ch === "\n";

/** True for characters the renderer cannot draw faithfully: not in the font (emoji, symbols, other scripts). */
export function isUnsupportedChar(face: Face, ch: string): boolean {
  if (isLineBreak(ch)) return false;
  return !face.advances.has(ch.codePointAt(0)!);
}

/** Characters of right-to-left scripts (Arabic, Hebrew, Syriac, Thaana): drawtext cannot shape or order them. */
export function isRightToLeft(ch: string): boolean {
  const cp = ch.codePointAt(0)!;
  return (cp >= 0x0590 && cp <= 0x08ff) || (cp >= 0xfb1d && cp <= 0xfdff) || (cp >= 0xfe70 && cp <= 0xfeff);
}

/** Width in pixels of text on one line (unsupported characters count as a space). */
export function measureLine(face: Face, text: string, fontSizePx: number): number {
  let milli = 0;
  for (const ch of text) milli += face.advances.get(ch.codePointAt(0)!) ?? face.data.space;
  return (milli * fontSizePx) / 1000;
}

export interface Wrapped {
  lines: string[];
  /** Characters the font cannot draw, once each. */
  unsupported: string[];
  rightToLeft: boolean;
}

/**
 * Greedy word wrap to `maxWidthPx`. Explicit line breaks are kept; a word wider than a line is split between characters.
 * Spaces at a break are dropped (they would only make the line look off-centre).
 */
export function wrapText(face: Face, text: string, fontSizePx: number, maxWidthPx: number): Wrapped {
  const unsupported = new Set<string>();
  let rightToLeft = false;
  for (const ch of text) {
    if (isRightToLeft(ch)) rightToLeft = true;
    if (isUnsupportedChar(face, ch)) unsupported.add(ch);
  }
  const trim = (s: string) => s.replace(TRAILING_SPACES, "");
  const lines: string[] = [];
  for (const paragraph of text.split("\n")) {
    if (paragraph.trim() === "") {
      lines.push("");
      continue;
    }
    let line = "";
    const flush = () => {
      lines.push(trim(line));
      line = "";
    };
    for (const word of paragraph.split(AFTER_SPACE)) {
      // `word` keeps its trailing space so spacing is exact
      if (measureLine(face, trim(line + word), fontSizePx) <= maxWidthPx) {
        line += word;
        continue;
      }
      if (line !== "") flush();
      if (measureLine(face, trim(word), fontSizePx) <= maxWidthPx) {
        line = word;
        continue;
      }
      // a single word wider than the line: break between characters
      for (const ch of word) {
        if (line !== "" && measureLine(face, line + ch, fontSizePx) > maxWidthPx) flush();
        line += ch;
      }
    }
    if (line !== "") flush();
  }
  return { lines: lines.map((l) => (isSpace(l) ? "" : l)), unsupported: [...unsupported], rightToLeft };
}
